S, K, J = '"Sanga of the Thunder"', '"Kazejin"', '"Suijin"'
TRIO = S + ', ' + K + ' o ' + J
def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def gg_leave(a, b): return ' Si esta carta Invocada de Modo Especial boca arriba en control de su dueño deja el Campo por una carta de tu adversario: puedes Invocar de Modo Especial 1 de tus "%s" o "%s" desterrados.' % (a, b)
EYE = 'Una vez mientras esté boca arriba en el Campo, durante el cálculo de daño en el turno de tu adversario, si esta carta está siendo atacada (Efecto Rápido): puedes seleccionar al monstruo atacante; su ATK se convierte en 0 sólo durante el cálculo de daño.'
BACK = ' Puedes desterrar esta carta de tu Cementerio; añade a tu mano 1 de tus ' + TRIO + ' que esté desterrado o en tu Deck.'
ES = {
"Gate Guardian of Thunder and Wind": S + ' + ' + K + '\nDebe ser Invocada de Modo Especial (desde tu Extra Deck) desterrando las cartas de arriba que controles. Durante tu Main Phase: puedes añadir a tu mano, desde tu Deck, 1 Mágica/Trampa que mencione a ' + S + ', ' + K + ' Y ' + J + '.' + once("Gate Guardian of Thunder and Wind") + gg_leave("Sanga of the Thunder", "Kazejin"),
"Gate Guardian of Water and Thunder": J + ' + ' + S + '\nDebe ser Invocada de Modo Especial (desde tu Extra Deck) desterrando las cartas de arriba que controles. Una vez por Cadena (Efecto Rápido): puedes seleccionar 1 monstruo boca arriba que controle tu adversario; su ATK se convierte en 0 hasta el final de este turno. Sólo puedes usar este efecto de "Gate Guardian of Water and Thunder" dos veces por turno.' + gg_leave("Suijin", "Sanga of the Thunder"),
"Gate Guardian of Wind and Water": K + ' + ' + J + '\nDebe ser Invocada de Modo Especial (desde tu Extra Deck) desterrando las cartas de arriba que controles. Una vez por Cadena, cuando tu adversario active una Carta o efecto Mágico/de Trampa en el Campo (Efecto Rápido): puedes negar ese efecto. Sólo puedes usar este efecto de "Gate Guardian of Wind and Water" dos veces por turno.' + gg_leave("Kazejin", "Suijin"),
"Gate Guardians Combined": S + ' + ' + K + ' + ' + J + '\nDebe ser Invocada de Modo Especial (desde tu Extra Deck) desterrando las cartas de arriba de tu mano, Campo y/o Cementerio. Cuando tu adversario active una carta o efecto que seleccione una o más cartas que controles (Efecto Rápido): puedes negar ese efecto y, si lo haces, destruye esa carta. Sólo puedes usar este efecto de "Gate Guardians Combined" tres veces por turno. Si esta carta Invocada de Modo Especial boca arriba en control de su dueño deja el Campo por una carta de tu adversario: puedes Invocar de Modo Especial 1 monstruo "Gate Guardian" de Nivel 11 o menor desde tu Deck o Extra Deck, ignorando sus condiciones de Invocación.',
"Gate Guardian": 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial (desde tu mano) Sacrificando 1 ' + S + ', 1 ' + K + ' y 1 ' + J + '.',
"Dark Guardian": '(Esta carta siempre se trata como una carta "Gate Guardian".)\nNo puede ser Invocada de Modo Normal ni Colocada. Debe ser Invocada de Modo Especial por "Dark Element", o Invocada de Modo Especial (desde tu mano o Cementerio) barajando en el Deck 1 de cada uno de tus ' + S + ', ' + K + ' y ' + J + ' que estén en tu mano, boca arriba en tu Campo, en tu Cementerio y/o desterrados. No puede ser destruida en batalla. Si esta carta es Invocada de Modo Especial por el efecto de "Dark Element", no es afectada por los efectos de otros monstruos ni por las Cartas o efectos Mágicos activados de tu adversario.',
"Guardian Elma": 'No puede ser Invocada a menos que controles un "Butterfly Dagger - Elma" boca arriba. Cuando esta carta sea Invocada de Modo Normal o Especial: puedes seleccionar 1 Carta Mágica de Equipo apropiada en tu Cementerio; equípala a esta carta.',
"Guardian Baou": 'No puede ser Invocada a menos que controles un "Wicked-Breaking Flamberge - Baou" boca arriba. Cuando esta carta destruya en batalla un monstruo de tu adversario y lo mande al Cementerio: gana 1000 ATK. Niega los efectos de los monstruos destruidos en batalla con esta carta.',
"Guardian Ceal": 'No puede ser Invocada a menos que controles un "Shooting Star Bow - Ceal" boca arriba. Puedes mandar al Cementerio 1 Carta Mágica de Equipo que controles equipada a esta carta para seleccionar 1 monstruo que controle tu adversario; destrúyelo.',
"Guardian Kay'est": 'No puede ser Invocada a menos que controles un "Rod of Silence - Kay\'est" boca arriba. Esta carta no es afectada por efectos Mágicos y no puede ser seleccionada para ataques, pero eso no impide que tu adversario te ataque directamente.',
"Guardian Grarl": 'No puede ser Invocada a menos que controles un "Gravity Axe - Grarl" boca arriba. Si es la única carta en tu mano, puedes Invocarla de Modo Especial (desde tu mano).',
"Guardian Tryce": 'No puede ser Invocada a menos que controles un "Twin Swords of Flashing Light - Tryce" boca arriba. Cuando esta carta sea destruida y mandada al Cementerio: Invoca de Modo Especial desde el Cementerio el monstruo que fue Sacrificado para su Invocación por Sacrificio.',
"Kazejin": EYE,
"Sanga of the Thunder": EYE,
"Suijin": EYE,
"Labyrinth Heavy Tank": 'Puedes Invocar esta carta de Modo Normal sin Sacrificar. No puede atacar el turno en que es Invocada de Modo Normal. Durante tu Main Phase: puedes colocar 1 de tus ' + TRIO + ' que esté desterrado, o en tu mano o Deck, boca arriba en tu Zona de Mágicas y Trampas como una Mágica Continua y, después, si controlas una carta "Labyrinth Wall", puedes destruir 1 monstruo que controle tu adversario.' + once("Labyrinth Heavy Tank"),
"Guardian Dreadscythe": 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial desde la mano con su propio efecto, y no puede ser Invocada de Modo Especial de otras formas, excepto desde el Cementerio con su propio efecto. Si un "Guardian Eatos" es destruido en batalla o por un efecto de carta y mandado a tu Cementerio: puedes Invocar esta carta de Modo Especial desde tu mano. Cuando esta carta sea Invocada de Modo Especial: puedes equipar a esta carta 1 "Reaper Scythe - Dreadscythe" de tu Deck. No puedes Invocar monstruos de Modo Normal ni Especial (pero puedes Colocar de Modo Normal). Si esta carta es mandada del Campo al Cementerio: manda 1 carta de tu mano al Cementerio y, si lo haces, Invoca esta carta de Modo Especial desde el Cementerio.',
"Guardian Eatos": 'Si no tienes monstruos en tu Cementerio, puedes Invocar esta carta de Modo Especial (desde tu mano). Puedes mandar al Cementerio 1 de tus Mágicas de Equipo equipadas a esta carta y, después, seleccionar hasta 3 monstruos en el Cementerio de tu adversario; destiérralos y, si lo haces, esta carta gana 500 ATK por cada monstruo desterrado por este efecto, hasta el final de este turno.',
"Butterfly Dagger - Elma": 'El monstruo equipado gana 300 ATK. Cuando esta carta sea destruida y mandada al Cementerio mientras está equipada: puedes devolver esta carta a la mano.',
"Celestial Sword - Eatos": '(Esta carta siempre se trata como una carta "Noble Arms".)\nEl monstruo equipado gana 500 ATK. Cuando esta carta sea mandada del Campo al Cementerio: puedes seleccionar 1 "Guardian Eatos" que controles; gana 500 ATK por cada monstruo desterrado.',
"Dark Element": 'Si tienes un monstruo "Gate Guardian" en tu Cementerio: paga la mitad de tus LP; Invoca de Modo Especial 1 monstruo "Gate Guardian" de Nivel 11 o mayor desde tu mano, Deck o Extra Deck, ignorando sus condiciones de Invocación. Puedes desterrar esta carta de tu Cementerio; añade a tu mano 1 de tus ' + TRIO + ' de tu Deck o de entre tus cartas desterradas.' + each("Dark Element"),
"Double Attack! Wind and Thunder!!": 'Si controlas un monstruo "Gate Guardian": selecciona 1 carta en el Campo; destrúyela. Durante tu Main Phase: puedes desterrar esta carta de tu Cementerio; añade a tu mano 1 de tus ' + TRIO + ' que esté desterrado o en tu Deck.' + once("Double Attack! Wind and Thunder!!"),
"Gravity Axe - Grarl": 'El monstruo equipado gana 500 ATK. Los monstruos que controle tu adversario no pueden cambiar su posición de batalla.',
"Labyrinth Wall Shadow": 'Los monstruos no pueden atacar el turno en que son Invocados, excepto los monstruos cuyo Nivel original sea 5 o mayor. Una vez por turno, durante tu Main Phase: puedes colocar 1 de tus ' + TRIO + ' que esté desterrado, o en tu mano o Deck, boca arriba en tu Zona de Mágicas y Trampas como una Mágica Continua. Al comienzo de la Battle Phase de tu adversario: puedes seleccionar 1 monstruo que controle tu adversario con menos de 1600 ATK; destrúyelo.',
"Power of the Guardians": 'Si se declara un ataque que involucre al monstruo equipado: pon 1 Contador de Magia en esta carta. El monstruo equipado gana 500 ATK/DEF por cada Contador de Magia en esta carta. Si el monstruo equipado fuera a ser destruido en batalla o por un efecto de carta, en su lugar puedes retirar 1 Contador de Magia de tu Campo.',
"Reaper Scythe - Dreadscythe": 'Equipa sólo a "Guardian Dreadscythe". Gana 500 ATK por cada monstruo en los Cementerios.',
"Riryoku Guardian": 'Si tus LP son menores que los de tu adversario: selecciona 1 monstruo que controles con "Gate Guardian" en su nombre original; reduce a la mitad los LP de tu adversario y, después, ese monstruo gana ATK igual a los LP de tu adversario.' + BACK + each("Riryoku Guardian"),
"Rod of Silence - Kay'est": 'El monstruo equipado gana 500 DEF. Niega los demás efectos Mágicos que seleccionen al monstruo equipado y, si lo haces, destruye esa Carta Mágica.',
"Shooting Star Bow - Ceal": 'El monstruo equipado pierde 1000 ATK, pero puede atacar directamente a tu adversario.',
"Twin Swords of Flashing Light - Tryce": 'Manda 1 carta de tu mano al Cementerio; equipa esta carta a un monstruo. Pierde 500 ATK, pero puede realizar un segundo ataque durante cada Battle Phase.',
"Wicked-Breaking Flamberge - Baou": 'Manda 1 carta de tu mano al Cementerio y, después, selecciona 1 monstruo en el Campo; equipa esta carta a ese monstruo. Gana 500 ATK. Niega los efectos de los monstruos de tu adversario destruidos en batalla con el monstruo equipado.',
"Prey of the Jirai Gumo": 'Invoca esta carta de Modo Especial como un Monstruo Normal (Tipo Insecto/TIERRA/Nivel 5/ATK 2100/DEF 100) en tu Zona de Monstruos Principal de su misma columna (esta carta también sigue siendo una Trampa) y, después, puedes destruir 1 monstruo que controle tu adversario en la columna de esta carta.' + BACK + each("Prey of the Jirai Gumo"),
}
